 "risks": [
  {
   "id": "no_termination_right",
   "severity": "medium",
   "message": "The lease has no early termination clause, so Northwind is committed to the full 3-year term (about $288,000 in base rent) with no stated exit.",
   "quote": "The initial term of this Agreement is three (3) years (the \"Initial Term\")."
  },
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "No limitation of liability clause exists, so Northwind's exposure to the landlord is uncapped.",
   "quote": "Each Party warrants that it will perform its obligations in a professional and workmanlike manner"
  },
  {
   "id": "security_deposit",
   "severity": "low",
   "message": "Two months' base rent (about $16,000) must be paid up front. The lease does not say when or how it is returned.",
   "quote": "Tenant shall deliver a security deposit equal to two months' base rent."
  },
  {
   "id": "missing_lease_terms",
   "severity": "medium",
   "message": "The lease does not state the rent due date, late fees, rent escalation, renewal rent, or maintenance and repair responsibilities, which leaves ambiguity for Northwind.",
   "quote": "Tenant shall pay annual base rent of $96,000, payable in equal monthly installments."
  },
  {
   "id": "renewal_notice_unspecified",
   "severity": "low",
   "message": "The 5-year renewal option requires written notice but gives no deadline or rent terms, so it may be hard to exercise or enforce.",
   "quote": "Tenant shall have one (1) option to renew the Lease for an additional five (5) years by giving written notice."
  },
  {
   "id": "exclusive_california_courts",
   "severity": "low",
   "message": "Disputes must be brought exclusively in California courts, which may be inconvenient if Northwind is based elsewhere.",
   "quote": "Any dispute shall be resolved exclusively in the courts located in California"
  }
 ],
 "injection_attempt": false,
 "summary": "Northwind Labs, Inc. leases office space at 400 Harbor Street, Suite 12 from Granite Row Properties LLC for an initial 3 years starting 15 July 2026, at $96,000 a year in base rent. Northwind has one option to renew for 5 years, but the lease has no early termination right or liability cap, and it leaves several key lease terms unstated."
}
